args.sql:
SELECT COUNT(*) FROM (
    SELECT srkeys, MAX((contentvols->'standard_content'->>'Ep_Vol')::int) as max_ep
    FROM show_rollups
    GROUP BY srkeys
    HAVING MAX((contentvols->'standard_content'->>'Ep_Vol')::int) > 100
) sub;

SELECT COUNT(DISTINCT srkeys) FROM (
    SELECT srkeys, MAX((contentvols->'standard_content'->>'Ep_Vol')::int) as max_ep
    FROM show_rollups
    GROUP BY srkeys
    HAVING MAX((contentvols->'standard_content'->>'Ep_Vol')::int) > 100
) sub;
